        raise ValueError("Valor do pedido não pode ser negativo.")

    # 2. Tarifa base por peso
    if peso_kg <= 1:
        tarifa_base = 12.00
    elif 1 < peso_kg <= 5:
        # kg adicional = ceil(peso - 1)
        fractions = math.ceil(peso_kg - 1)
        tarifa_base = 12.00 + fractions * 3.50
    else:  # peso_kg > 5
        # kg adicional = ceil(peso - 5)
        fractions = math.ceil(peso_kg - 5)
        tarifa_base = 26.00 + fractions * 2.80

    # 3. Multiplicador regional
    multiplicadores = {"S": 1.00, "SE": 1.00, "CO": 1.20, "NE": 1.35, "N": 1.50}
    multiplicador = multiplicadores[regiao]
    tarifa_base_multiplicada = tarifa_base * multiplicador

    # 4. Expresso
    tarifa_expresso = tarifa_base_multiplicada * 1.40 if expresso else tarifa_base_multiplicada

    # 5. Frete grátis (Override)
    is_frete_gratis = (valor_pedido >= 299.90 and not expresso and regiao in ["S", "SE", "CO"])

    if is_frete_gratis:
        frete = 0.0
    else:
        frete = tarifa_expresso

        # 6. Cupons
        cupom_limpo = cupom.upper() if cupom else None

        if cupom_limpo == "FRETE10":
            frete *= 0.90
        elif cupom_limpo == "FRETEMETADE":
            if peso_kg <= 5:
                frete *= 0.50
            # else: cupom é ignorado
        elif cupom_limpo is None or cupom_limpo == "":
            pass # Sem cupom
        else:
            raise ValueError("Cupom inválido.")

        # 7. Frete mínimo (Exceto frete grátis)
        if frete != 0.0:
            frete = max(frete, 9.90)

    # 8. Arredondamento comercial (ROUND_HALF_UP)
    # Convert to Decimal for precise rounding
    frete_decimal = Decimal(str(frete))
    resultado_arredondado = frete_decimal.quantize(Decimal("0.00"), rounding=ROUND_HALF_UP)

